function initW_wplane(root, D) {
  // 축소판 5편: kobis_movies.csv를 movieCd 오름차순 정렬한 뒤 인덱스 3·44·48·93·205(모두 학습 150편 소속)
  // [제목, 스크린(100관), 성수기, 실제 총 관객(만명)]
  const MINI = [['끝장수사', 6.48, 0, 8.5], ['굿 포츈', 3.53, 1, 2.4], ['햄넷', 3.81, 0, 5.6], ['국보', 4.84, 0, 19.1], ['마티 슈프림', 7.38, 1, 13.2]];

  // 가우스 소거로 정규방정식을 푼다(정답 수치 하드코딩 없음)
  function solveOLS(A, b) {
    const n = A.length, M = A.map((r, i) => r.concat([b[i]]));
    for (let c = 0; c < n; c++) {
      let p = c;
      for (let r = c + 1; r < n; r++) if (Math.abs(M[r][c]) > Math.abs(M[p][c])) p = r;
      const t = M[c]; M[c] = M[p]; M[p] = t;
      const pv = M[c][c];
      for (let j = c; j <= n; j++) M[c][j] /= pv;
      for (let r = 0; r < n; r++) {
        if (r === c) continue;
        const f = M[r][c];
        if (!f) continue;
        for (let j = c; j <= n; j++) M[r][j] -= f * M[c][j];
      }
    }
    return M.map(r => r[n]);
  }
  function fit(cols) {
    const k = cols.length, A = [], bv = [];
    for (let i = 0; i < k; i++) { A.push(new Array(k).fill(0)); bv.push(0); }
    for (const m of MINI) {
      const f = cols.map(c => c(m)), y = m[3];
      for (let i = 0; i < k; i++) { for (let j = 0; j < k; j++) A[i][j] += f[i] * f[j]; bv[i] += f[i] * y; }
    }
    return solveOLS(A, bv);
  }
  const sse = (w1, w2, b) => MINI.reduce((s, m) => { const e = w1 * m[1] + w2 * m[2] + b - m[3]; return s + e * e; }, 0);

  const BEST = fit([m => m[1], m => m[2], () => 1]);        // 2.0123 · −4.0951 · 0.9179
  const BSSE = sse(BEST[0], BEST[1], BEST[2]);              // 114.631
  const FIXB = fit([m => m[1], () => 1]);                   // 1.8324 · 0.2171
  const FSSE = sse(FIXB[0], 0, FIXB[1]);                    // 134.390

  // 좌표: x 스크린 3~8 → 470~700, y 총 관객 0~22 → 290~70
  const sx = v => 470 + (v - 3) / 5 * 230;
  const sy = v => 290 - v / 22 * 220;

  const q = s => root.querySelector(s);
  const eq = q('.eq'), rows = q('.rows'), bar = q('.bar'), saw = q('.saw'), sseT = q('.sse');
  const l0 = q('.l0'), l1 = q('.l1'), ref = q('.ref'), reflab = q('.reflab'), marks = q('.marks');
  const s1 = q('.s1'), s2 = q('.s2'), s3 = q('.s3');
  const v1 = q('.v1'), v2 = q('.v2'), v3 = q('.v3');
  const bfix = q('.bfix'), bbest = q('.bbest'), bref = q('.bref'), fixnote = q('.fixnote');

  // 표기는 반올림한 값 기준(−0.0·−0.00 방지). 색 판정도 표기값을 따른다
  const r2 = v => { const t = Math.round(v * 100) / 100; return t === 0 ? 0 : t; };
  const r1 = v => { const t = Math.round(v * 10) / 10; return t === 0 ? 0 : t; };
  const num2 = v => { const t = r2(v); return (t < 0 ? '−' : '') + Math.abs(t).toFixed(2); };
  const num1 = v => { const t = r1(v); return (t < 0 ? '−' : '') + Math.abs(t).toFixed(1); };
  const sgn2 = v => { const t = r2(v); return (t < 0 ? ' − ' : ' + ') + Math.abs(t).toFixed(2); };

  q('.refsse').textContent = '최소제곱 정답 ' + BSSE.toFixed(2);
  reflab.textContent = '성수기 빼고 구한 직선 ' + FIXB[0].toFixed(2);
  const FIXNOTE = '고정 상태 최선 w₁ ' + FIXB[0].toFixed(2) + ' · b ' + FIXB[1].toFixed(2) + ' · 오차 제곱합 ' + FSSE.toFixed(2);

  // 표 다섯 행(정적 칸은 한 번만 그린다)
  const RY = [112, 144, 176, 208, 240];
  rows.innerHTML = MINI.map((m, i) => {
    const y = RY[i];
    return '<text x="20" y="' + y + '">' + m[0] + '</text>' +
      '<text x="200" y="' + y + '" text-anchor="end">' + m[1].toFixed(2) + '</text>' +
      '<text x="258" y="' + y + '" text-anchor="end">' + m[2] + '</text>' +
      '<text x="322" y="' + y + '" text-anchor="end">' + m[3].toFixed(1) + '</text>' +
      '<text class="pv" x="380" y="' + y + '" text-anchor="end">0.0</text>' +
      '<text class="ev" x="428" y="' + y + '" text-anchor="end">0.0</text>';
  }).join('');
  const pvs = Array.prototype.slice.call(root.querySelectorAll('.pv'));
  const evs = Array.prototype.slice.call(root.querySelectorAll('.ev'));

  // 점 다섯 개: 성수기 0은 파란 원, 성수기 1은 흰 원에 노란 테두리
  q('.dots').innerHTML = MINI.map(m => m[2] === 0
    ? '<circle cx="' + sx(m[1]).toFixed(1) + '" cy="' + sy(m[3]).toFixed(1) + '" r="4" fill="#2b7fd6" opacity=".8"/>'
    : '<circle cx="' + sx(m[1]).toFixed(1) + '" cy="' + sy(m[3]).toFixed(1) + '" r="4" fill="#fff" stroke="#b07a00" stroke-width="2"/>').join('');

  // 직선을 패널 안으로 잘라 그린다(clipPath는 id가 필요하므로 사용하지 않는다)
  function clip(m, c) {
    let lo = 3, hi = 8;
    if (Math.abs(m) < 1e-9) return (c < 0 || c > 22) ? null : { lo: lo, hi: hi, a: false, b: false };
    const xa = (0 - c) / m, xb = (22 - c) / m;
    lo = Math.max(3, Math.min(xa, xb));
    hi = Math.min(8, Math.max(xa, xb));
    if (hi - lo < 1e-6) return null;
    return { lo: lo, hi: hi, a: lo > 3 + 1e-6, b: hi < 8 - 1e-6 };
  }
  function tri(x, y, up, fill) {
    const p = up ? (x + ',' + (y - 1) + ' ' + (x - 5) + ',' + (y + 7) + ' ' + (x + 5) + ',' + (y + 7))
      : (x + ',' + (y + 1) + ' ' + (x - 5) + ',' + (y - 7) + ' ' + (x + 5) + ',' + (y - 7));
    return '<polygon points="' + p + '" fill="' + fill + '"/>';
  }
  function drawLine(el, m, c, fill, out) {
    const s = clip(m, c);
    if (!s) { el.setAttribute('visibility', 'hidden'); return; }
    el.setAttribute('visibility', 'visible');
    el.setAttribute('x1', sx(s.lo).toFixed(1)); el.setAttribute('y1', sy(m * s.lo + c).toFixed(1));
    el.setAttribute('x2', sx(s.hi).toFixed(1)); el.setAttribute('y2', sy(m * s.hi + c).toFixed(1));
    if (s.a) out.push(tri(+sx(s.lo).toFixed(1), +sy(m * s.lo + c).toFixed(1), m < 0, fill));
    if (s.b) out.push(tri(+sx(s.hi).toFixed(1), +sy(m * s.hi + c).toFixed(1), m > 0, fill));
  }

  let w1 = 1, w2 = 0, b = 0, refOn = false, fixOn = false, savedW2 = 0, seq = 0;

  function render() {
    eq.textContent = '예측 = ' + num2(w1) + '×스크린' + sgn2(w2) + '×성수기' + sgn2(b);
    let tot = 0;
    MINI.forEach((m, i) => {
      const p = w1 * m[1] + w2 * m[2] + b, e = (p - m[3]) * (p - m[3]);
      tot += e;
      pvs[i].textContent = num1(p);
      pvs[i].setAttribute('fill', r1(p) < 0 ? '#d64545' : '#1c2230');
      evs[i].textContent = num1(e);
    });
    bar.setAttribute('width', Math.max(0, Math.min(tot, 300)).toFixed(1));
    saw.setAttribute('visibility', tot > 300 ? 'visible' : 'hidden');
    sseT.textContent = num1(tot);
    v1.textContent = num2(w1); v2.textContent = num2(w2); v3.textContent = num2(b);

    const out = [];
    drawLine(l0, w1, b, '#2b7fd6', out);
    drawLine(l1, w1, b + w2, '#b07a00', out);
    if (refOn) drawLine(ref, FIXB[0], FIXB[1], '#b9b3a5', out);
    else ref.setAttribute('visibility', 'hidden');
    reflab.setAttribute('visibility', refOn ? 'visible' : 'hidden');
    marks.innerHTML = out.join('');
  }

  function syncSliders() { s1.value = w1.toFixed(2); s2.value = w2.toFixed(2); s3.value = b.toFixed(2); }

  function run(dur, step) {
    const token = ++seq;
    let t0 = -1;
    const frame = ts => {
      if (token !== seq) return;
      if (t0 < 0) t0 = ts;
      const t = Math.min(1, (ts - t0) / dur);
      step(1 - (1 - t) * (1 - t));
      syncSliders(); render();
      if (t < 1) requestAnimationFrame(frame);
    };
    requestAnimationFrame(frame);
  }

  s1.addEventListener('input', () => { seq++; w1 = +s1.value; render(); });
  s2.addEventListener('input', () => { seq++; w2 = +s2.value; render(); });
  s3.addEventListener('input', () => { seq++; b = +s3.value; render(); });

  bfix.addEventListener('click', () => {
    seq++;
    fixOn = !fixOn;
    bfix.classList.toggle('on', fixOn);
    bfix.setAttribute('aria-pressed', fixOn ? 'true' : 'false');
    if (fixOn) {
      savedW2 = w2; w2 = 0; s2.disabled = true;
      fixnote.textContent = FIXNOTE;
      syncSliders(); render();
    } else {
      s2.disabled = false;
      fixnote.textContent = '';
      const to = savedW2;
      run(300, k => { w2 = to * k; });
    }
  });

  bbest.addEventListener('click', () => {
    seq++;
    if (fixOn) {
      fixOn = false; bfix.classList.remove('on');
      bfix.setAttribute('aria-pressed', 'false');
      s2.disabled = false; fixnote.textContent = '';
    }
    const a0 = w1, b0 = w2, c0 = b;
    run(500, k => { w1 = a0 + (BEST[0] - a0) * k; w2 = b0 + (BEST[1] - b0) * k; b = c0 + (BEST[2] - c0) * k; });
  });

  bref.addEventListener('click', () => {
    refOn = !refOn;
    bref.classList.toggle('on', refOn);
    bref.setAttribute('aria-pressed', refOn ? 'true' : 'false');
    render();
  });

  syncSliders();
  render();
}
function initW_r2meaning(root, D) {
  // ── 색·좌표 상수 ──────────────────────────────────────────────
  const BLUE = '#2b7fd6', RED = '#d64545', GREY = '#b9b3a5',
        SUB = '#6b7385', INK = '#1c2230', GRID = '#e3ddcf';
  const X0 = 56, X1 = 428, Y0 = 44, Y1 = 258;   // 산점도 상자
  const UNIT = 10000;                            // 만 명
  const TOPN = 40;                               // 첫 주 관객 수 상위 40편
  const BARX = 460, BARMAX = 160;

  // 글자 폭 어림: 한글 1.0em, 나머지 0.55em
  const tw = (t, f) => {
    let w = 0;
    for (let i = 0; i < t.length; i++) w += t.charCodeAt(i) > 0x2000 ? f : f * 0.55;
    return w;
  };
  const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const f2 = v => (Math.round(v * 100) / 100).toFixed(2);
  const comma = v => {
    const s = String(Math.round(v)), out = [];
    for (let i = s.length; i > 0; i -= 3) out.unshift(s.slice(Math.max(0, i - 3), i));
    return out.join(',');
  };

  // ── 데이터: 첫 주 관객 수 상위 40편 ───────────────────────────
  const rows = D.slice()
    .sort((p, q) => (q[3] - p[3]) || (p[7] < q[7] ? -1 : p[7] > q[7] ? 1 : 0))
    .slice(0, TOPN);
  const P = rows.map(r => ({ x: r[3] / UNIT, y: r[4] / UNIT, name: r[7] }));
  const N = P.length;

  // ── 최소제곱 직선 ─────────────────────────────────────────────
  let mx = 0, my = 0;
  for (let i = 0; i < N; i++) { mx += P[i].x; my += P[i].y; }
  mx /= N; my /= N;
  let sxx = 0, sxy = 0;
  for (let i = 0; i < N; i++) { const dx = P[i].x - mx; sxx += dx * dx; sxy += dx * (P[i].y - my); }
  const b = sxx > 0 ? sxy / sxx : 0, a = my - b * mx;

  // ── 네 가지 예측 ──────────────────────────────────────────────
  const PRED = {
    perfect: P.map(p => p.y),
    fit:     P.map(p => a + b * p.x),
    mean:    P.map(() => my),
    wrong:   P.map(p => my - b * (p.x - mx))
  };
  const ss = pred => { let s = 0; for (let i = 0; i < N; i++) { const d = P[i].y - pred[i]; s += d * d; } return s; };
  const SST = ss(PRED.mean);
  const SSE = { perfect: ss(PRED.perfect), fit: ss(PRED.fit), mean: ss(PRED.mean), wrong: ss(PRED.wrong) };
  const R2 = {};
  Object.keys(SSE).forEach(k => { R2[k] = SST > 0 ? 1 - SSE[k] / SST : 0; });

  // ── 축 눈금 ───────────────────────────────────────────────────
  const niceStep = v => {
    const p = Math.pow(10, Math.floor(Math.log10(v))), f = v / p;
    return (f <= 1 ? 1 : f <= 2 ? 2 : f <= 2.5 ? 2.5 : f <= 5 ? 5 : 10) * p;
  };
  const axis = arr => {
    const mv = Math.max.apply(null, arr), st = niceStep(Math.max(mv, 1) / 4);
    const top = Math.ceil(mv / st) * st, t = [];
    for (let v = 0; v <= top + st * 0.001; v += st) t.push(v);
    return { top: top, ticks: t };
  };
  const AX = axis(P.map(p => p.x)), AY = axis(P.map(p => p.y));
  const sx = v => X0 + (X1 - X0) * (v / AX.top);
  const sy = v => Y1 - (Y1 - Y0) * (v / AY.top);
  const clampY = v => Math.max(Y0, Math.min(Y1, v));

  // ── 격자·눈금 그리기(고정) ────────────────────────────────────
  let g = '';
  AY.ticks.forEach(v => {
    const y = sy(v);
    g += '<line x1="' + X0 + '" y1="' + y.toFixed(1) + '" x2="' + X1 + '" y2="' + y.toFixed(1) +
         '" stroke="' + GRID + '"/>' +
         '<text x="50" y="' + (y + 4).toFixed(1) + '" font-size="12" text-anchor="end" fill="' + SUB + '">' + comma(v) + '</text>';
  });
  AX.ticks.forEach(v => {
    const x = sx(v);
    g += '<text x="' + x.toFixed(1) + '" y="274" font-size="12" text-anchor="middle" fill="' + SUB + '">' + comma(v) + '</text>';
  });
  g += '<line x1="' + X0 + '" y1="' + Y1 + '" x2="' + X1 + '" y2="' + Y1 + '" stroke="' + SUB + '"/>' +
       '<line x1="' + X0 + '" y1="' + Y0 + '" x2="' + X0 + '" y2="' + Y1 + '" stroke="' + SUB + '"/>';
  root.querySelector('.grid').innerHTML = g;

  // ── 점(고정) ──────────────────────────────────────────────────
  root.querySelector('.marks').innerHTML = P.map(p =>
    '<circle cx="' + sx(p.x).toFixed(1) + '" cy="' + sy(p.y).toFixed(1) + '" r="3.5" fill="' + BLUE + '" opacity=".55"/>'
  ).join('');

  // ── 이름표: 총 관객 수 상위 6편, 겹치면 자리 이동·생략 ────────
  const FS = 12;
  const cand = P.slice().sort((p, q) => q.y - p.y).slice(0, 6);
  // 축 이름·눈금 라벨 자리를 미리 막아 둔다(데이터가 바뀌어도 겹치지 않게)
  const box = [{ l: 10, r: 10 + tw('총 관객 수(만 명)', 13), t: 17, b: 33 }];
  AY.ticks.forEach(v => { const w = tw(comma(v), 12); box.push({ l: 50 - w, r: 50, t: sy(v) - 8, b: sy(v) + 7 }); });
  AX.ticks.forEach(v => { const w = tw(comma(v), 12); box.push({ l: sx(v) - w / 2, r: sx(v) + w / 2, t: 262, b: 277 }); });
  let lab = '';
  cand.forEach(p => {
    const cx = sx(p.x), cy = sy(p.y), w = tw(p.name, FS);
    const opts = [
      { x: cx + 8, y: cy + 4, an: 'start', l: cx + 8, r: cx + 8 + w },
      { x: cx - 8, y: cy + 4, an: 'end', l: cx - 8 - w, r: cx - 8 },
      { x: cx, y: cy - 10, an: 'middle', l: cx - w / 2, r: cx + w / 2 },
      { x: cx, y: cy + 18, an: 'middle', l: cx - w / 2, r: cx + w / 2 }
    ];
    for (let i = 0; i < opts.length; i++) {
      const o = opts[i], t = o.y - FS, bt = o.y + 3;
      if (o.l < 10 || o.r > 440 || t < 16 || bt > Y1 + 8) continue;
      let hit = false;
      for (let j = 0; j < box.length; j++) {
        const q = box[j];
        if (o.l < q.r + 4 && o.r + 4 > q.l && t < q.b + 3 && bt + 3 > q.t) { hit = true; break; }
      }
      if (hit) continue;
      box.push({ l: o.l, r: o.r, t: t, b: bt });
      lab += '<text x="' + o.x.toFixed(1) + '" y="' + o.y.toFixed(1) + '" font-size="' + FS +
             '" text-anchor="' + o.an + '" fill="' + INK + '">' + esc(p.name) + '</text>';
      break;
    }
  });
  root.querySelector('.labels').innerHTML = lab;

  // ── 선분 자르기(상자 밖 제거) ─────────────────────────────────
  function clip(x1, y1, x2, y2) {
    let t0 = 0, t1 = 1;
    const dx = x2 - x1, dy = y2 - y1;
    const pq = [[-dx, x1 - X0], [dx, X1 - x1], [-dy, y1 - Y0], [dy, Y1 - y1]];
    for (let i = 0; i < 4; i++) {
      const p = pq[i][0], q = pq[i][1];
      if (p === 0) { if (q < 0) return null; continue; }
      const r = q / p;
      if (p < 0) { if (r > t1) return null; if (r > t0) t0 = r; }
      else { if (r < t0) return null; if (r < t1) t1 = r; }
    }
    return [x1 + t0 * dx, y1 + t0 * dy, x1 + t1 * dx, y1 + t1 * dy];
  }

  // ── 문구 ──────────────────────────────────────────────────────
  const WHY = {
    perfect: ['모든 점을 그대로 통과', '내 오차 제곱합 0'],
    fit:     ['점 가까이 지나는 직선', '평균보다 작은 오차'],
    mean:    ['모든 영화를 평균으로', '평균과 똑같은 오차'],
    wrong:   ['방향이 반대인 직선', '평균보다 큰 오차 → 음수']
  };

  const lineG = root.querySelector('.lines');
  const r2T = root.querySelector('.r2val'), why1 = root.querySelector('.why1'), why2 = root.querySelector('.why2');
  const bar1 = root.querySelector('.bar1'), bar2 = root.querySelector('.bar2');
  const b1v = root.querySelector('.bar1v'), b2v = root.querySelector('.bar2v');
  const ratioT = root.querySelector('.ratio'), outT = root.querySelector('.wout');
  const btns = root.querySelectorAll('.wbtn');

  function draw(mode) {
    const pred = PRED[mode];
    let s = '';
    // 빨간 오차 선분
    if (mode !== 'perfect') {
      for (let i = 0; i < N; i++) {
        const x = sx(P[i].x), ya = sy(P[i].y), yp = clampY(sy(pred[i]));
        if (Math.abs(ya - yp) < 0.4) continue;
        s += '<line x1="' + x.toFixed(1) + '" y1="' + ya.toFixed(1) + '" x2="' + x.toFixed(1) + '" y2="' + yp.toFixed(1) +
             '" stroke="' + RED + '" stroke-width="1.2" opacity=".8"/>';
      }
    }
    // 예측선(파랑)
    if (mode === 'perfect') {
      const ord = P.map((p, i) => i).sort((i, j) => P[i].x - P[j].x);
      s += '<polyline fill="none" stroke="' + BLUE + '" stroke-width="1.8" points="' +
           ord.map(i => sx(P[i].x).toFixed(1) + ',' + sy(P[i].y).toFixed(1)).join(' ') + '"/>';
    } else {
      const yL = mode === 'mean' ? my : mode === 'fit' ? a : my + b * mx;
      const yR = mode === 'mean' ? my : mode === 'fit' ? a + b * AX.top : my - b * (AX.top - mx);
      const c = clip(sx(0), sy(yL), sx(AX.top), sy(yR));
      if (c) s += '<line x1="' + c[0].toFixed(1) + '" y1="' + c[1].toFixed(1) + '" x2="' + c[2].toFixed(1) +
                  '" y2="' + c[3].toFixed(1) + '" stroke="' + BLUE + '" stroke-width="2"/>';
    }
    // 평균선(회색 파선). 항상 맨 위
    s += '<line x1="' + X0 + '" y1="' + sy(my).toFixed(1) + '" x2="' + X1 + '" y2="' + sy(my).toFixed(1) +
         '" stroke="' + GREY + '" stroke-width="1.4" stroke-dasharray="5 4"/>';
    lineG.innerHTML = s;

    // 오른쪽 판
    const e = SSE[mode], r = R2[mode];
    r2T.textContent = (r < 0 ? '−' : '') + f2(Math.abs(r));
    r2T.setAttribute('fill', r < 0 ? RED : INK);
    why1.textContent = WHY[mode][0];
    why2.textContent = WHY[mode][1];
    const sc = BARMAX / Math.max(e, SST, 1);
    const w1 = Math.max(0, e * sc), w2 = SST * sc;
    bar1.setAttribute('width', w1.toFixed(1));
    bar2.setAttribute('width', w2.toFixed(1));
    b1v.setAttribute('x', (BARX + w1 + 6).toFixed(1));
    b2v.setAttribute('x', (BARX + w2 + 6).toFixed(1));
    b1v.textContent = comma(e);
    b2v.textContent = comma(SST);
    ratioT.textContent = '오차 제곱합의 비 = ' + (SST > 0 ? f2(e / SST) : '0.00');
    outT.textContent = '첫 주 관객 수 상위 ' + N + '편 · 예측선 파랑 · 평균선 회색 파선 · 오차 빨강';
    for (let i = 0; i < btns.length; i++) {
      btns[i].className = btns[i].getAttribute('data-m') === mode ? 'wbtn on' : 'wbtn';
    }
  }

  for (let i = 0; i < btns.length; i++) {
    btns[i].addEventListener('click', function () { draw(this.getAttribute('data-m')); });
  }
  draw('fit');
}

function initW_monthaudi(root, D) {
  const q = s => root.querySelector(s);
  const L = 56, R = 696, T = 36, B = 252, SW = (R - L) / 12;

  // ── 수치는 전부 D에서 계산한다(영진위 자료가 매일 갱신되므로 고정값 금지)
  const med = a => {
    if (!a.length) return null;
    const s = a.slice().sort((x, y) => x - y), h = s.length >> 1;
    return s.length % 2 ? s[h] : (s[h - 1] + s[h]) / 2;
  };
  const grp = [];
  for (let m = 1; m <= 12; m++) grp.push(D.filter(r => r[6] === m));
  const meds = grp.map(g => med(g.map(r => r[4])));
  const PEAK = [];                                   // 성수기 열(0/1)에서 직접 읽는다
  for (let m = 1; m <= 12; m++) {
    const g = grp[m - 1];
    let c = 0; g.forEach(r => { if (r[2] === 1) c++; });
    if (g.length && c * 2 > g.length) PEAK.push(m);
  }
  const pkV = D.filter(r => r[2] === 1).map(r => r[4]);
  const rsV = D.filter(r => r[2] !== 1).map(r => r[4]);

  const vals = D.map(r => r[4]).filter(v => v > 0);
  const lo = Math.log10(Math.min.apply(null, vals)) - 0.08;
  const hi = Math.log10(Math.max.apply(null, vals)) + 0.08;
  const cx = m => L + (m - 0.5) * SW;
  const sy = v => B - (Math.log10(v) - lo) / (hi - lo) * (B - T);
  const jit = i => { const h = ((i * 9301 + 49297) % 233280) / 233280; return (h - 0.5) * 34; };

  const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const man = v => { const n = v / 10000; return (n >= 100 ? Math.round(n) : Math.round(n * 10) / 10).toFixed(n >= 100 ? 0 : 1) + '만 명'; };
  const wid = (s, f) => { let w = 0; for (const ch of s) w += /[가-힣ㄱ-ㅎㅏ-ㅣ一-鿿]/.test(ch) ? f : f * 0.55; return w; };

  // ── 한 번만 그리는 층
  const tick = [];
  for (let d = Math.ceil(lo); d <= Math.floor(hi); d++) {
    const y = sy(Math.pow(10, d)), n = Math.pow(10, d - 4);
    tick.push('<line x1="' + L + '" y1="' + y.toFixed(1) + '" x2="' + R + '" y2="' + y.toFixed(1) + '" stroke="#e3ddcf" stroke-width="1"/>'
      + '<text x="' + (L - 8) + '" y="' + (y + 5).toFixed(1) + '" text-anchor="end" font-size="14" fill="#6b7385">' + (n >= 1 ? String(n) : n.toFixed(1)) + '</text>');
  }
  q('.grid').innerHTML = tick.join('');

  q('.bgs').innerHTML = PEAK.map(m =>
    '<rect x="' + (cx(m) - SW / 2).toFixed(1) + '" y="' + T + '" width="' + SW.toFixed(1) + '" height="' + (B - T) + '" fill="#b07a00" opacity="0.12"/>').join('');

  q('.meds').innerHTML = meds.map((v, i) => v === null ? '' :
    '<line x1="' + (cx(i + 1) - 19).toFixed(1) + '" y1="' + sy(v).toFixed(1) + '" x2="' + (cx(i + 1) + 19).toFixed(1) + '" y2="' + sy(v).toFixed(1) + '" stroke="#1c2230" stroke-width="3.4" stroke-linecap="round"/>').join('');

  const mp = meds.map((v, i) => v === null ? null : [cx(i + 1), sy(v)]).filter(p => p);
  q('.mline').innerHTML = '<polyline points="' + mp.map(p => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join(' ') + '" fill="none" stroke="#2b7fd6" stroke-width="2.6"/>'
    + mp.map(p => '<circle cx="' + p[0].toFixed(1) + '" cy="' + p[1].toFixed(1) + '" r="4" fill="#2b7fd6"/>').join('');

  q('.cmp').innerHTML =
    '<text x="' + L + '" y="298" font-size="14" font-weight="700" fill="#b07a00">성수기 ' + PEAK.join('·') + '월 · ' + pkV.length + '편 중앙값 ' + man(med(pkV)) + '</text>'
    + '<text x="380" y="298" font-size="14" fill="#6b7385">나머지 ' + (12 - PEAK.length) + '개월 · ' + rsV.length + '편 중앙값 ' + man(med(rsV)) + '</text>';

  const top = D.slice().sort((a, b) => b[4] - a[4]).slice(0, 4);
  const bgs = q('.bgs'), mline = q('.mline'), cmp = q('.cmp');
  const btn = { all: q('.ball'), med: q('.bmed'), pk: q('.bpk') };

  function draw(mode) {
    const dim = mode === 'med', pk = mode === 'peak';
    q('.pts').innerHTML = D.map((r, i) => r[4] > 0
      ? '<circle cx="' + (cx(r[6]) + jit(i)).toFixed(1) + '" cy="' + sy(r[4]).toFixed(1) + '" r="3.5" fill="' + (dim ? '#b9b3a5' : '#2b7fd6') + '" opacity="' + (dim ? .3 : .55) + '"/>'
      : '').join('');
    q('.xlab').innerHTML = meds.map((v, i) => {
      const on = pk && PEAK.indexOf(i + 1) >= 0;
      return '<text x="' + cx(i + 1).toFixed(1) + '" y="272" text-anchor="middle" font-size="14" fill="' + (on ? '#b07a00' : '#6b7385') + '"' + (on ? ' font-weight="700"' : '') + '>' + (i + 1) + '월</text>';
    }).join('');
    bgs.setAttribute('visibility', pk ? 'visible' : 'hidden');
    mline.setAttribute('visibility', dim ? 'visible' : 'hidden');
    cmp.setAttribute('visibility', pk ? 'visible' : 'hidden');

    // 이름표: 서로 겹치지 않게 아래로 밀고, 밀린 것에는 이음선을 붙인다
    const used = [], out = [];
    top.forEach(r => {
      const nm = String(r[7]).trim();
      const px = cx(r[6]) + jit(D.indexOf(r)), py = sy(r[4]);
      const w = wid(nm, 14) + 4;
      const right = px + 10 + w <= 712;
      const tx = right ? px + 10 : px - 10;
      const x1 = right ? tx : tx - w, x2 = x1 + w;
      let ty = py + 5;
      for (let g = 0; g < 30; g++) {
        let hit = false;
        for (const u of used) if (x1 < u[2] && x2 > u[0] && ty - 12 < u[3] && ty + 4 > u[1]) hit = true;
        if (!hit) break;
        ty += 17;
      }
      ty = Math.min(ty, B - 4);
      used.push([x1, ty - 12, x2, ty + 4]);
      if (ty > py + 9) out.push('<line x1="' + px.toFixed(1) + '" y1="' + py.toFixed(1) + '" x2="' + tx.toFixed(1) + '" y2="' + (ty - 4).toFixed(1) + '" stroke="#b9b3a5" stroke-width="1"/>');
      out.push('<text x="' + tx.toFixed(1) + '" y="' + ty.toFixed(1) + '" text-anchor="' + (right ? 'start' : 'end') + '" font-size="14" font-weight="700" fill="' + (dim ? '#6b7385' : '#1c2230') + '" stroke="#ffffff" stroke-width="3" paint-order="stroke" stroke-linejoin="round">' + esc(nm) + '</text>');
    });
    q('.labs').innerHTML = out.join('');

    const st = { all: mode === 'all', med: dim, pk: pk };
    ['all', 'med', 'pk'].forEach(k => {
      btn[k].classList.toggle('on', st[k]);
      btn[k].setAttribute('aria-pressed', st[k] ? 'true' : 'false');
    });
  }

  btn.all.addEventListener('click', () => draw('all'));
  btn.med.addEventListener('click', () => draw('med'));
  btn.pk.addEventListener('click', () => draw('peak'));
  draw('all');
}

function initW_monthlong(root, D) {
  // 22년치 개봉월별 중앙값. scripts/lesson07_month_medians.py 가 값을 다시 쓴다.
  const M = window.MONTH_LONG;
  if (!M) return;
  const VAC = [1, 2, 7, 8];              // 방학이 낀 달
  const PEAK = [12, 1, 7, 8];            // 성수기
  const X0 = 66, X1 = 700, Y0 = 44, Y1 = 250;
  const top = Math.max.apply(null, M.months.map(r => r[2])) * 1.12;
  const bw = (X1 - X0) / 12 * 0.62;
  const cx = i => X0 + (X1 - X0) / 12 * (i + 0.5);
  const py = v => Y1 - (v / top) * (Y1 - Y0);

  const q = sel => root.querySelector(sel);
  const gBar = q('[data-dyn="bars"]'), gLab = q('[data-dyn="labs"]');
  const line = q('[data-dyn="base"]'), tBase = q('[data-t="base"]');
  const tOut = q('[data-t="out"]');
  const btns = Array.prototype.slice.call(root.querySelectorAll('.wbtn'));
  let mode = 'peak';

  const NS = 'http://www.w3.org/2000/svg';
  const mk = (tag, at) => { const e = document.createElementNS(NS, tag);
    for (const k in at) e.setAttribute(k, at[k]); return e; };

  function draw() {
    gBar.textContent = ''; gLab.textContent = '';
    M.months.forEach(function (r, i) {
      const m = r[0], med = r[2];
      const on = mode === 'peak' ? PEAK.indexOf(m) >= 0 : VAC.indexOf(m) >= 0;
      const fill = on ? (mode === 'peak' ? '#2b7fd6' : '#e8930c') : '#cfd4de';
      gBar.appendChild(mk('rect', { x: cx(i) - bw / 2, y: py(med), width: bw,
        height: Y1 - py(med), fill: fill, rx: 3 }));
      const lab = mk('text', { x: cx(i), y: Y1 + 18, 'text-anchor': 'middle',
        'font-size': 13, fill: on ? '#1c2230' : '#7a7f95',
        'font-weight': on ? 800 : 500 });
      lab.textContent = m + '월';
      gLab.appendChild(lab);
      if (m === 2) {
        const t = mk('text', { x: cx(i), y: py(med) - 8, 'text-anchor': 'middle',
          'font-size': 12, 'font-weight': 800, fill: '#e45756' });
        t.textContent = '2월';
        gLab.appendChild(t);
      }
    });
    line.setAttribute('x1', X0); line.setAttribute('x2', X1);
    line.setAttribute('y1', py(M.med)); line.setAttribute('y2', py(M.med));
    tBase.setAttribute('y', py(M.med) - 6);
    tBase.textContent = '전체 중앙값 ' + M.med.toLocaleString() + '명';
    const feb = M.months[1][2], ratio = (feb / M.med).toFixed(2);
    tOut.textContent = mode === 'peak'
      ? '성수기 네 달(12·1·7·8월)이 전체 중앙값 위에 있습니다'
      : '방학이 낀 네 달 가운데 2월만 전체 중앙값 아래입니다 · 2월 ' + ratio + '배';
  }

  btns.forEach(function (b) {
    b.addEventListener('click', function () {
      mode = b.dataset.act;
      btns.forEach(function (x) {
        x.classList.toggle('on', x === b);
        x.setAttribute('aria-pressed', x === b ? 'true' : 'false');
      });
      draw();
    });
  });
  draw();
}

function initW_plane3d(root, D) {
  // 속성 하나(직선)와 둘(평면)을 같은 영화로 비교한다.
  // 값은 scripts/lesson07_plane_data.py 가 다시 쓴다. [스크린수, 배우 수, 총 관객(만명), 제목]
  const P = window.PLANE_DATA;
  if (!P) return;
  const X0 = 78, X1 = 660, Y0 = 40, Y1 = 268;          // 그림 영역
  const sMin = 100, sMax = 1600, aMin = 0, aMax = 20, yMax = 340;

  function ols(two) {                                   // 정규방정식을 가우스 소거로 푼다
    const k = two ? 3 : 2, A = [], b = [];
    for (let i = 0; i < k; i++) { A.push(new Array(k).fill(0)); b.push(0); }
    for (const r of P) {
      const f = two ? [1, r[0], r[1]] : [1, r[0]];
      for (let i = 0; i < k; i++) { for (let j = 0; j < k; j++) A[i][j] += f[i] * f[j]; b[i] += f[i] * r[2]; }
    }
    const M = A.map((row, i) => row.concat([b[i]]));
    for (let c = 0; c < k; c++) {
      let piv = c;
      for (let r = c + 1; r < k; r++) if (Math.abs(M[r][c]) > Math.abs(M[piv][c])) piv = r;
      const t = M[c]; M[c] = M[piv]; M[piv] = t;
      const pv = M[c][c];
      for (let j = c; j <= k; j++) M[c][j] /= pv;
      for (let r = 0; r < k; r++) {
        if (r === c) continue;
        const f = M[r][c]; if (!f) continue;
        for (let j = c; j <= k; j++) M[r][j] -= f * M[c][j];
      }
    }
    return M.map(r => r[k]);
  }
  function r2(w, two) {
    const mean = P.reduce((s, r) => s + r[2], 0) / P.length;
    let sse = 0, sst = 0;
    for (const r of P) {
      const p = two ? w[0] + w[1] * r[0] + w[2] * r[1] : w[0] + w[1] * r[0];
      sse += (r[2] - p) * (r[2] - p); sst += (r[2] - mean) * (r[2] - mean);
    }
    return 1 - sse / sst;
  }
  const W1 = ols(false), W2 = ols(true);
  const R1 = r2(W1, false), R2 = r2(W2, true);

  let two = false, ang = 32;                            // 보기 각도(도)
  const q = sel => root.querySelector(sel);
  const NS = 'http://www.w3.org/2000/svg';
  const mk = (t, at) => { const e = document.createElementNS(NS, t);
    for (const k in at) e.setAttribute(k, at[k]); return e; };
  const gFit = q('[data-dyn="fit"]'), gDot = q('[data-dyn="dots"]'), gAx = q('[data-dyn="ax"]');
  const tR2 = q('[data-t="r2"]'), tEq = q('[data-t="eq"]'), tDep = q('[data-t="dep"]');
  const rng = q('.ang'), rngWrap = q('.angwrap');
  const btns = Array.prototype.slice.call(root.querySelectorAll('.wbtn'));

  // 3차원 좌표를 화면으로. 깊이축(배우 수)은 오른쪽 위로 비스듬히 눕힌다.
  function proj(scrn, actors, audi) {
    const u = (scrn - sMin) / (sMax - sMin);
    const v = two ? (actors - aMin) / (aMax - aMin) : 0;
    const rad = ang * Math.PI / 180;
    const DX = 138, DY = 26;                            // 깊이축이 쓰는 화면 폭과 높이
    const x = X0 + u * (X1 - X0) * 0.72 + v * DX * Math.cos(rad);
    const y = Y1 - (audi / yMax) * (Y1 - Y0 - DY) - v * DY * Math.sin(rad);
    return [x, y];
  }
  const pred = (s, a) => two ? W2[0] + W2[1] * s + W2[2] * a : W1[0] + W1[1] * s;

  function draw() {
    gAx.textContent = ''; gFit.textContent = ''; gDot.textContent = '';

    if (two) {                                          // 깊이축 눈금
      const c0 = proj(sMin, 0, 0), c1 = proj(sMin, aMax, 0);
      gAx.appendChild(mk('line', { x1: c0[0], y1: c0[1], x2: c1[0], y2: c1[1],
        stroke: '#b9b3a5', 'stroke-width': 1.2 }));
      const lab = mk('text', { x: c1[0] + 6, y: c1[1] - 4, 'font-size': 12, fill: '#7a7f95' });
      lab.textContent = '배우 ' + aMax + '명';
      gAx.appendChild(lab);
    }

    // 적합면: 격자 몇 줄만 그린다
    // 예측이 0보다 작아지는 구간은 그리지 않는다. 축 아래로 삐져나간다
    const from = a => {
      const w = two ? W2 : W1, base = two ? w[0] + w[2] * a : w[0];
      return Math.max(sMin, Math.min(sMax, -base / w[1]));
    };
    const AS = two ? [0, 7, 14, aMax] : [0];
    AS.forEach(function (a, i) {
      const s0 = from(a);
      const p1 = proj(s0, a, pred(s0, a)), p2 = proj(sMax, a, pred(sMax, a));
      gFit.appendChild(mk('line', { x1: p1[0], y1: p1[1], x2: p2[0], y2: p2[1],
        stroke: '#2b7fd6', 'stroke-width': i === 0 ? 2.4 : 1.2,
        opacity: i === 0 ? 1 : 0.5 }));
    });
    if (two) {
      [sMin, (sMin + sMax) / 2, sMax].forEach(function (s) {
        const a0 = Math.max(0, Math.min(aMax, -(W2[0] + W2[1] * s) / W2[2]));
        const p1 = proj(s, a0, pred(s, a0)), p2 = proj(s, aMax, pred(s, aMax));
        gFit.appendChild(mk('line', { x1: p1[0], y1: p1[1], x2: p2[0], y2: p2[1],
          stroke: '#2b7fd6', 'stroke-width': 1.2, opacity: 0.5 }));
      });
    }

    P.forEach(function (r) {
      const p = proj(r[0], two ? r[1] : 0, r[2]);
      const c = mk('circle', { cx: p[0], cy: p[1], r: 3.4, fill: '#1c2230', opacity: 0.62 });
      const ttl = mk('title'); ttl.textContent = r[3] + ' · 스크린 ' + r[0] + '관 · 배우 ' + r[1] + '명 · ' + r[2] + '만 명';
      c.appendChild(ttl); gDot.appendChild(c);
    });

    tR2.textContent = 'R² ' + (two ? R2 : R1).toFixed(3);
    const put = v => (v < 0 ? ' − ' : ' + ') + Math.abs(v).toFixed(1);
    tEq.textContent = two
      ? '예측 = ' + W2[1].toFixed(3) + ' × 스크린수 + ' + W2[2].toFixed(2) + ' × 배우 수' + put(W2[0])
      : '예측 = ' + W1[1].toFixed(3) + ' × 스크린수' + put(W1[0]);
    tDep.textContent = two ? '축이 하나 늘어 직선이 평면이 됩니다' : '속성 하나로는 직선입니다';
    rngWrap.hidden = !two;
  }

  btns.forEach(function (b) {
    b.addEventListener('click', function () {
      two = b.dataset.act === 'two';
      btns.forEach(function (x) {
        x.classList.toggle('on', x === b);
        x.setAttribute('aria-pressed', x === b ? 'true' : 'false');
      });
      draw();
    });
  });
  rng.addEventListener('input', function () { ang = +rng.value; draw(); });
  draw();
}
  const WIDGET_INIT = {wplane: initW_wplane, r2meaning: initW_r2meaning, monthaudi: initW_monthaudi, monthlong: initW_monthlong, plane3d: initW_plane3d};
  function initWidgets(scope) { (scope || document).querySelectorAll('.widget[data-w]').forEach(el => { if (el.dataset.ready) return; const f = WIDGET_INIT[el.dataset.w]; if (f) { f(el, window.LESSON_DATA); el.dataset.ready = '1'; } }); }
  window.initWidgets = initWidgets;
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => initWidgets()); else initWidgets();
